/// fixed point float representation. 18 decimal places are kept.
module math::float;

use math::math_error;

const U64_MAX_256: u256 = 18446744073709551615u256;
// VALUE_MAX_256 = U64_MAX_256 * WAD
const VALUE_MAX_256: u256 = 18446744073709551615000000000000000000u256;
const WAD: u256 = 1000000000000000000;

public struct Decimal has copy, drop, store {
    value: u256,
}

public fun zero(): Decimal { Decimal { value: 0 } }

public fun one(): Decimal { from(1) }

public fun from(v: u64): Decimal { Decimal { value: (v as u256) * WAD } }

public fun from_quotient(numerator: u64, denominator: u64): Decimal {
    Decimal {
        value: ensure_decimal_value_safe((numerator as u256) * WAD / (denominator as u256)),
    }
}

public fun is_zero(a: &Decimal): bool {
    a.value == 0
}

public fun add(a: Decimal, b: Decimal): Decimal {
    Decimal {
        value: ensure_decimal_value_safe(a.value + b.value),
    }
}

public fun add_u64(a: &Decimal, b: u64): Decimal {
    let value = b as u256 * WAD;
    Decimal {
        value: ensure_decimal_value_safe(a.value + value),
    }
}

public fun sub(a: Decimal, b: Decimal): Decimal {
    Decimal {
        value: a.value - b.value,
    }
}

public fun sub_u64(a: Decimal, b: u64): Decimal {
    let value = from(b);
    sub(a, value)
}

public fun saturating_sub(a: Decimal, b: Decimal): Decimal {
    if (a.value < b.value) {
        Decimal { value: 0 }
    } else {
        Decimal { value: a.value - b.value }
    }
}

public fun int_mul(a: Decimal, b: u64): u64 {
    safe_from_u256((a.value * (b as u256)) / WAD)
}

